// Tests: autogenerated (tests/auto_<table>.json) and custom (tests/<table>.json), run in a
// transaction that is rolled back.
import { api, esc, attempt, dialog, confirmAction, method, statusClass, json, toast } from "../ui.js";

let state = { tests: [], errors: [], results: {}, filter: "" };

const EXAMPLE = {
  description: "Describe what the test checks",
  steps: [
    { request: { method: "POST", path: "/my_table", as: 1, body: { column: "value" } }, expect: { status: 201 }, save: { id: "lastId" } },
    { request: { method: "GET", path: "/my_table/${id}" }, expect: { status: 200, row: { column: "value" } } },
  ],
};

export async function render(main, app) {
  main.innerHTML = `
    <h1>Tests</h1>
    <p class="sa-muted">Each test runs inside a transaction that is rolled back: the database is left as it was.
      They can also be run in the console with <code>silence test</code>.</p>
    <div class="sa-toolbar">
      <button class="ez-button" type="button" id="run">Run all</button>
      <button class="ez-button ez-button--secondary" type="button" id="generate">Generate from the endpoints</button>
      <button class="ez-button ez-button--secondary" type="button" id="new">New composed test</button>
      <span class="sa-toolbar__spacer"></span>
      <span id="summary"></span>
      <label for="filter" class="sa-muted">Table</label>
      <select id="filter"><option value="">All</option></select>
    </div>
    <div id="errors"></div>
    <div id="list"></div>`;

  main.querySelector("#generate").addEventListener("click", async () => {
    const ok = await confirmAction("Generate the tests",
      "The files tests/auto_<table>.json are written again from the endpoints and the current data. " +
      "The custom tests (tests/<table>.json) are kept.", "Generate");
    if (!ok) return;
    const res = await attempt(() => api("/tests/generate", "POST", {}));
    if (res) {
      toast(`${res.tables.reduce((a, t) => a + t.tests, 0)} tests generated`, "success");
      state.results = {};
      await app.refreshStatus();
      load(main);
    }
  });
  main.querySelector("#run").addEventListener("click", () => run(main, null));
  main.querySelector("#new").addEventListener("click", () => edit(main, null));
  main.querySelector("#filter").addEventListener("change", (e) => {
    state.filter = e.target.value;
    draw(main);
  });
  load(main);
}

async function load(main) {
  const res = await attempt(() => api("/tests"));
  if (!res) return;
  state.tests = res.tests;
  state.errors = res.errors;
  const tables = [...new Set(res.tests.map((t) => t.table))].sort();
  main.querySelector("#filter").innerHTML = `<option value="">All</option>` +
    tables.map((t) => `<option ${t === state.filter ? "selected" : ""}>${esc(t)}</option>`).join("");
  draw(main);
}

async function run(main, names) {
  const button = main.querySelector("#run");
  button.disabled = true;
  button.setAttribute("aria-busy", "true");
  const visible = names ?? (state.filter ? state.tests.filter((t) => t.table === state.filter).map((t) => t.name) : null);
  const res = await attempt(() => api("/tests/run", "POST", { names: visible }));
  button.disabled = false;
  button.removeAttribute("aria-busy");
  if (!res) return;
  for (const r of res.results) {
    state.results[r.name] = r;
  }
  const passed = res.results.filter((r) => r.passed).length;
  toast(`${passed} of ${res.results.length} tests passed`, passed === res.results.length ? "success" : "warning");
  draw(main);
}

function draw(main) {
  main.querySelector("#errors").innerHTML = state.errors.length
    ? `<div class="ez-alert ez-alert--error"><strong>Tests not loaded</strong>
        <ul>${state.errors.map((e) => `<li>${esc(e)}</li>`).join("")}</ul></div>` : "";
  const results = Object.values(state.results);
  const passed = results.filter((r) => r.passed).length;
  main.querySelector("#summary").innerHTML = results.length
    ? `<span class="${passed === results.length ? "sa-pass" : "sa-fail"}">${passed} / ${results.length} passed</span>` : "";

  const tests = state.tests.filter((t) => !state.filter || t.table === state.filter);
  const list = main.querySelector("#list");
  if (!tests.length) {
    list.innerHTML = `<p class="sa-muted">No tests yet: generate them from the endpoints.</p>`;
    return;
  }
  const byTable = {};
  for (const t of tests) {
    (byTable[t.table] ??= []).push(t);
  }
  list.innerHTML = Object.entries(byTable).sort().map(([table, items]) => `
    <section class="sa-section">
      <h2>${esc(table)}</h2>
      <div class="ez-scroll"><table class="sa-table">
        <thead><tr><th>Result</th><th>Test</th><th>File</th><th></th></tr></thead>
        <tbody>${items.map(row).join("")}</tbody>
      </table></div>
    </section>`).join("");

  for (const button of list.querySelectorAll("[data-action]")) {
    const t = state.tests.find((x) => x.name === button.dataset.name);
    button.addEventListener("click", () => actions[button.dataset.action](main, t));
  }
}

function row(t) {
  const r = state.results[t.name];
  const result = !r ? `<span class="sa-muted">—</span>` : r.passed ? `<span class="sa-pass">PASS</span>` : `<span class="sa-fail">FAIL</span>`;
  const first = t.data.steps[0]?.request ?? {};
  const badge = t.source === "auto" ? `<span class="ez-badge">auto</span>` : `<span class="ez-badge ez-badge--primary">custom</span>`;
  return `
    <tr>
      <td>${result}</td>
      <td><strong>${esc(t.name)}</strong> ${t.composite ? `<span class="ez-badge">${t.data.steps.length} steps</span>` : ""}<br>
        <span class="sa-small">${method(first.method ?? "GET")} <span class="sa-route">${esc(first.path)}</span></span><br>
        <span class="sa-muted sa-small">${esc(t.description)}</span>
        ${r && !r.passed ? stepsDetail(r.steps) : ""}</td>
      <td class="sa-small">${badge}<br>${esc(t.file)}</td>
      <td class="sa-actions">
        <button class="ez-button sa-button--small" type="button" data-action="run" data-name="${esc(t.name)}">Run</button>
        ${t.source === "auto"
          ? `<button class="ez-button ez-button--secondary sa-button--small" type="button" data-action="customize" data-name="${esc(t.name)}">Customize</button>`
          : `<button class="ez-button ez-button--secondary sa-button--small" type="button" data-action="edit" data-name="${esc(t.name)}">Edit</button>
             <button class="ez-button ez-button--danger sa-button--small" type="button" data-action="remove" data-name="${esc(t.name)}">Delete</button>`}
      </td>
    </tr>`;
}

function stepsDetail(steps) {
  return steps.map((s) => `
    <div class="sa-step ${s.passed ? "sa-step--pass" : "sa-step--fail"} sa-small">
      Step ${s.index + 1}: ${method(s.method)} <span class="sa-route">${esc(s.path)}</span>
      ${s.status ? `→ <span class="sa-status ${statusClass(s.status)}">${s.status}</span>` : ""}
      ${s.failures.length ? `<br>${s.failures.map(esc).join("<br>")}
        <details><summary>Response</summary><pre class="sa-pre">${json(s.response)}</pre></details>` : ""}
    </div>`).join("");
}

const actions = {
  run(main, t) {
    run(main, [t.name]);
  },
  async customize(main, t) {
    const ok = await confirmAction("Customize the test",
      `${t.name} moves from ${t.file} to ${t.table}.json, where you can change it. Generating the tests again will not overwrite it.`, "Move to custom");
    if (!ok) return;
    if (await attempt(() => api("/tests/customize", "POST", { name: t.name }), "Moved")) {
      await load(main);
      edit(main, state.tests.find((x) => x.name === t.name));
    }
  },
  edit(main, t) {
    edit(main, t);
  },
  async remove(main, t) {
    if (await confirmAction("Delete the test", `${t.name} is removed from ${t.file}.`, "Delete")) {
      if (await attempt(() => api("/tests/custom", "DELETE", { file: t.file, name: t.name }), "Deleted")) {
        delete state.results[t.name];
        load(main);
      }
    }
  },
};

async function edit(main, t, draft) {
  const data = draft?.data ?? t?.data ?? EXAMPLE;
  const name = draft?.name ?? t?.name ?? "";
  const file = draft?.file ?? t?.file ?? (state.filter || "my_table") + ".json";
  const v = await dialog(t ? `Edit ${t.name}` : "New composed test", `
    <p class="sa-small sa-muted">Steps: <code>request</code> (method, path after the API prefix, <code>as</code>: the id of the user,
      body), <code>expect</code> (status, count, row, message) and <code>save</code> (variables for the next steps, as <code>\${name}</code>).</p>
    <div class="sa-form">
      <div class="ez-field"><label for="t-name">Name</label><input id="t-name" name="name" value="${esc(name)}" required pattern="\\w+"></div>
      <div class="ez-field"><label for="t-file">File (tests/)</label><input id="t-file" name="file" value="${esc(file)}" required pattern="[\\w-]+\\.json"></div>
    </div>
    <div class="ez-field"><label for="t-data">Test (JSON)</label>
      <textarea id="t-data" name="data" class="sa-code" spellcheck="false">${esc(JSON.stringify(data, null, 2))}</textarea></div>
    <div class="sa-toolbar"><button class="ez-button ez-button--secondary" type="button" id="t-try">Try the steps</button></div>
    <div id="t-result"></div>`, "Save");

  // The dialog is closed: bind "try" is done below, before awaiting, see bindTryInDialog
  if (!v) return;
  let parsed;
  try {
    parsed = JSON.parse(v.data);
  } catch {
    toast("The test is not valid JSON", "error");
    return edit(main, t, { name: v.name, file: v.file, data: v.data });
  }
  if (await attempt(() => api("/tests/custom", "PUT", { file: v.file, name: v.name, oldName: t?.name, data: parsed }), "Saved in tests/" + v.file)) {
    load(main);
  } else {
    edit(main, t, { name: v.name, file: v.file, data: parsed });
  }
}

// "Try the steps" inside the dialog: runs them rolled back and shows each result
document.addEventListener("click", async (event) => {
  if (event.target.id !== "t-try") return;
  const area = document.querySelector("#t-data");
  let parsed;
  try {
    parsed = JSON.parse(area.value);
  } catch {
    toast("The test is not valid JSON", "error");
    return;
  }
  const res = await attempt(() => api("/tests/try", "POST", { steps: parsed.steps }));
  if (res) {
    document.querySelector("#t-result").innerHTML = stepsDetail(res.steps) +
      (res.steps.length < parsed.steps.length ? `<p class="sa-small sa-muted">The next steps were not run.</p>` : "");
  }
});
